import Foundation
import XCTest

@testable import OrbitDropHelperCore

/// Runs tests/fixtures/wheel-golden.json (generated by scripts/gen-golden.mjs from the
/// TypeScript reference, owned by the core workstream) against the Swift port.
/// Every macOS-relevant section runs: hitTest, hitTestNonFinite, placement, arming,
/// selection, fileCount, coords.mac (AppKit flip), coords.displayForPoint, coords.clamp,
/// coords.rounding. coords.win is the Windows helper's (physical-pixel layout).
/// Override the file with ORBITDROP_GOLDEN=/path/to/wheel-golden.json.
final class GoldenTests: XCTestCase {
  static var goldenURL: URL {
    if let path = ProcessInfo.processInfo.environment["ORBITDROP_GOLDEN"], !path.isEmpty { return URL(fileURLWithPath: path) }
    return TestPaths.repoRoot.appendingPathComponent("tests/fixtures/wheel-golden.json")
  }

  private var golden: [String: Any] = [:]
  private var tolerance = 1e-6
  private var geometry = WheelGeometry.default

  override func setUpWithError() throws {
    let url = Self.goldenURL
    guard FileManager.default.fileExists(atPath: url.path) else {
      throw XCTSkip("golden vectors not found at \(url.path) (run node scripts/gen-golden.mjs)")
    }
    golden = try JSONSerialization.jsonObject(with: Data(contentsOf: url)) as! [String: Any]
    XCTAssertEqual(golden["formatVersion"] as? Int, 1, "golden layout changed: update the loader")
    tolerance = ((golden["tolerance"] as? [String: Any])?["dip"] as? NSNumber)?.doubleValue ?? 1e-6
    let g = golden["geometry"] as! [String: Any]
    for field in WheelGeometry.fieldRanges { geometry[keyPath: field.keyPath] = num(g[field.name]) }
  }

  // MARK: helpers

  /// JSON number, or one of the strings "NaN", "Infinity", "-Infinity".
  func num(_ value: Any?) -> Double {
    if let n = value as? NSNumber { return n.doubleValue }
    switch value as? String {
    case "NaN": return .nan
    case "Infinity": return .infinity
    case "-Infinity": return -.infinity
    default:
      XCTFail("not a number: \(String(describing: value))")
      return .nan
    }
  }

  func point(_ value: Any?) -> Point {
    let o = value as! [String: Any]
    return Point(x: num(o["x"]), y: num(o["y"]))
  }

  func rect(_ value: Any?) -> Rect {
    let o = value as! [String: Any]
    return Rect(x: num(o["x"]), y: num(o["y"]), width: num(o["width"]), height: num(o["height"]))
  }

  func close(_ a: Double, _ b: Double) -> Bool {
    if a.isNaN || b.isNaN { return a.isNaN && b.isNaN }
    if a.isInfinite || b.isInfinite { return a == b }
    return abs(a - b) <= tolerance
  }

  func close(_ a: Point, _ b: Point) -> Bool { close(a.x, b.x) && close(a.y, b.y) }
  func close(_ a: Rect, _ b: Rect) -> Bool { close(a.x, b.x) && close(a.y, b.y) && close(a.width, b.width) && close(a.height, b.height) }

  /// Per-section bookkeeping: counts cases, keeps the first failures, prints "GOLDEN section: passed/total".
  final class Section {
    let name: String
    var total = 0
    var failures: [String] = []
    init(_ name: String) { self.name = name }
    func check(_ ok: Bool, _ message: @autoclosure () -> String) {
      total += 1
      if !ok && failures.count < 400 { failures.append(message()) }
    }
    func finish(file: StaticString = #filePath, line: UInt = #line) {
      let passed = total - failures.count
      print("GOLDEN \(name): \(passed)/\(total) passed")
      XCTAssertGreaterThan(total, 0, "\(name): no cases", file: file, line: line)
      XCTAssertTrue(failures.isEmpty, "\(name): \(failures.count) failures\n" + failures.prefix(10).joined(separator: "\n"), file: file, line: line)
    }
  }

  func cases(_ section: String) -> [[String: Any]] {
    (golden[section] as? [String: Any])?["cases"] as? [[String: Any]] ?? []
  }

  func expectedHit(_ c: [String: Any]) -> RawWheelHit {
    switch c["zone"] as? String {
    case "center": return .center
    case "outside": return .outside
    default: return .sector(num(c["index"]))
    }
  }

  // MARK: sections

  func testHitTest() {
    let section = Section("hitTest")
    for c in cases("hitTest") {
      let n = num(c["n"]), d = num(c["d"]), dx = num(c["dx"]), dy = num(c["dy"])
      let expected = expectedHit(c)
      let got = WheelMath.hitTestRaw(dx: dx, dy: dy, sectorCount: n, diameter: d, geometry)
      section.check(got == expected, "hit(n=\(n), d=\(d), dx=\(dx), dy=\(dy)) = \(got), expected \(expected) [\(c["kind"] ?? "")]")
      // The Int API the session controller uses must agree for real menu sizes.
      if n == n.rounded(.towardZero), n >= 0, n <= 12 {
        let safe = WheelMath.hitTest(dx: dx, dy: dy, sectorCount: Int(n), diameter: d, geometry)
        let same: Bool
        switch (safe, expected) {
        case (.center, .center), (.outside, .outside): same = true
        case (.sector(let i), .sector(let e)): same = Double(i) == e
        default: same = false
        }
        section.check(same, "Int API hit(n=\(Int(n)), dx=\(dx), dy=\(dy)) = \(safe), expected \(expected)")
      }
    }
    section.finish()
  }

  func testHitTestNonFinite() {
    let section = Section("hitTestNonFinite")
    for c in cases("hitTestNonFinite") {
      let got = WheelMath.hitTestRaw(dx: num(c["dx"]), dy: num(c["dy"]), sectorCount: num(c["n"]), diameter: num(c["d"]), geometry)
      section.check(got == expectedHit(c), "non-finite \(c) → \(got)")
    }
    section.finish()
  }

  func testPlacement() {
    let section = Section("placement")
    for c in cases("placement") {
      var g = geometry
      g.diameter = num(c["diameter"])
      let activation = point(c["activation"])
      let workArea = rect(c["workArea"])
      let e = c["expect"] as! [String: Any]
      let p = WheelMath.placeWheel(activation: activation, workArea: workArea, g)
      let label = "\(c["workAreaName"] ?? "")/\(c["point"] ?? "") d=\(g.diameter)"
      section.check(close(p.center, point(e["center"])), "\(label): center \(p.center) ≠ \(point(e["center"]))")
      section.check(close(p.diameter, num(e["diameter"])), "\(label): diameter \(p.diameter) ≠ \(num(e["diameter"]))")
      section.check(close(p.windowFrame, rect(e["windowFrame"])), "\(label): windowFrame \(p.windowFrame) ≠ \(rect(e["windowFrame"]))")
      section.check(p.shifted == (e["shifted"] as! Bool), "\(label): shifted \(p.shifted)")
    }
    section.finish()
  }

  func testArming() {
    let section = Section("arming")
    for c in cases("arming") {
      var g = geometry
      g.armDistance = num(c["armDistance"])
      let got = WheelMath.isArmed(activation: point(c["activation"]), pointer: point(c["pointer"]), passedCenter: c["passedCenter"] as! Bool, g)
      section.check(got == (c["expect"] as! Bool), "arming \(c) → \(got)")
    }
    section.finish()
  }

  func testSelection() {
    let section = Section("selection")
    let selection = golden["selection"] as! [String: Any]
    let rawMaps = selection["extensionMaps"] as! [String: [String: String]]
    var maps: [String: [String: MenuKey]] = [:]
    for (name, raw) in rawMaps {
      // Values that are not menu keys simply never match (they count as unknown).
      maps[name] = raw.compactMapValues { MenuKey(rawValue: $0) }
    }
    for c in selection["cases"] as! [[String: Any]] {
      let map = maps[c["map"] as! String]!
      let paths = c["paths"] as! [String]
      let expected = c["expect"] as? String
      let got = Classifier.menuKeyForPaths(paths, extensions: map)?.rawValue
      section.check(got == expected, "\(c["note"] ?? ""): \(paths) → \(got ?? "null"), expected \(expected ?? "null")")
      // classify() (what the drop target uses) agrees for absolute file paths.
      if paths.allSatisfy({ $0.hasPrefix("/") }) && !paths.isEmpty {
        let items = paths.map { DragItem.file(path: $0, isDirectory: false) }
        section.check(Classifier.classify(items, extensions: map).menuKey?.rawValue == expected, "classify \(paths)")
      }
    }
    section.finish()
  }

  func testFileCount() {
    let section = Section("fileCount")
    let fileCount = golden["fileCount"] as! [String: Any]
    let reason = fileCount["multiFileReason"] as! String
    for c in fileCount["cases"] as! [[String: Any]] {
      let sectors = (c["sectors"] as! [[String: Any]]).map { s in
        WheelSector(actionId: ActionId(rawValue: s["actionId"] as! String)!, label: s["actionId"] as! String, icon: nil, enabled: s["enabled"] as! Bool, reason: s["reason"] as? String, batch: s["batch"] as! Bool)
      }
      let got = Classifier.adjustForFileCount(sectors, fileCount: c["fileCount"] as! Int, reason: reason)
      let expected = c["expect"] as! [[String: Any]]
      section.check(got.count == expected.count, "\(c["name"] ?? ""): count")
      for (g, e) in zip(got, expected) {
        section.check(g.actionId.rawValue == e["actionId"] as? String && g.enabled == e["enabled"] as? Bool && g.reason == e["reason"] as? String,
                      "\(c["name"] ?? "") fileCount=\(c["fileCount"] ?? ""): \(g.actionId.rawValue) enabled=\(g.enabled) reason=\(g.reason ?? "nil"), expected \(e)")
      }
    }
    section.finish()
  }

  /// macOS layouts: NSScreen frames → global DIP displays, AppKit points/rects, and the whole
  /// wheel chain (activation → display → placement → AppKit window frame → pointer hit-test).
  func testCoordsMac() {
    let section = Section("coords.mac")
    let layouts = (golden["coords"] as! [String: Any])["mac"] as! [[String: Any]]
    for layout in layouts {
      let name = layout["name"] as! String
      let screens = (layout["screens"] as! [[String: Any]]).map {
        AppKitScreen(id: $0["id"] as? String, frame: rect($0["frame"]), visibleFrame: rect($0["visibleFrame"]), backingScaleFactor: num($0["backingScaleFactor"]))
      }
      let primary = screens[0].frame
      let displays = Coords.displaysFromAppKitScreens(screens)
      let expectedDisplays = layout["displays"] as! [[String: Any]]
      section.check(displays.count == expectedDisplays.count, "\(name): display count")
      for (d, e) in zip(displays, expectedDisplays) {
        section.check(close(d.bounds, rect(e["bounds"])) && close(d.workArea, rect(e["workArea"])) && close(d.scaleFactor, num(e["scaleFactor"])) && d.primary == (e["primary"] as! Bool),
                      "\(name): display \(d) ≠ \(e)")
      }
      for p in layout["points"] as! [[String: Any]] {
        let global = Coords.appKitPointToGlobal(point(p["appKit"]), primaryFrame: primary)
        section.check(close(global, point(p["global"])), "\(name): point \(point(p["appKit"])) → \(global)")
        section.check(close(Coords.globalPointToAppKit(global, primaryFrame: primary), point(p["appKit"])), "\(name): point round trip")
        section.check(Coords.displayIndexAtPoint(global, displays.map(\.bounds)) == (p["displayIndex"] as! Int), "\(name): displayIndex of \(global)")
      }
      for r in layout["rects"] as! [[String: Any]] {
        let global = Coords.appKitRectToGlobal(rect(r["appKit"]), primaryFrame: primary)
        section.check(close(global, rect(r["global"])), "\(name): rect \(rect(r["appKit"])) → \(global)")
        section.check(close(Coords.globalRectToAppKit(global, primaryFrame: primary), rect(r["appKit"])), "\(name): rect round trip")
      }
      for w in layout["wheel"] as! [[String: Any]] {
        var g = geometry
        g.diameter = num(w["diameter"])
        let activation = Coords.appKitPointToGlobal(point(w["activationAppKit"]), primaryFrame: primary)
        section.check(close(activation, point(w["activation"])), "\(name): activation \(activation)")
        guard let placed = Coords.placeWheelOnDisplays(activation, displays, g) else {
          section.check(false, "\(name): no display for \(activation)")
          continue
        }
        let p = placed.placement
        section.check(placed.displayIndex == (w["displayIndex"] as! Int), "\(name): wheel displayIndex \(placed.displayIndex)")
        section.check(close(p.center, point(w["center"])), "\(name): center \(p.center) ≠ \(point(w["center"]))")
        section.check(close(p.diameter, num(w["placementDiameter"])), "\(name): placement diameter \(p.diameter)")
        section.check(close(p.windowFrame, rect(w["windowFrame"])), "\(name): windowFrame \(p.windowFrame)")
        section.check(close(Coords.globalRectToAppKit(p.windowFrame, primaryFrame: primary), rect(w["windowFrameAppKit"])), "\(name): NSPanel frame")
        section.check(p.shifted == (w["shifted"] as! Bool), "\(name): shifted \(p.shifted)")
        for ptr in w["pointers"] as! [[String: Any]] {
          // AppKit is y-up: convert to the y-down global space (equivalent to negating dy) before hit-testing.
          let pointer = Coords.appKitPointToGlobal(point(ptr["appKit"]), primaryFrame: primary)
          let got = WheelMath.hitTestRaw(dx: pointer.x - p.center.x, dy: pointer.y - p.center.y, sectorCount: num(ptr["sectorCount"]), diameter: p.diameter, g)
          section.check(got == expectedHit(ptr), "\(name): pointer \(point(ptr["appKit"])) → \(got), expected \(expectedHit(ptr))")
          // Same result through the raw AppKit delta with dy negated.
          let appKitCenter = Coords.globalPointToAppKit(p.center, primaryFrame: primary)
          let viaFlip = WheelMath.hitTestRaw(dx: point(ptr["appKit"]).x - appKitCenter.x, dy: -(point(ptr["appKit"]).y - appKitCenter.y), sectorCount: num(ptr["sectorCount"]), diameter: p.diameter, g)
          section.check(viaFlip == expectedHit(ptr), "\(name): pointer via negated AppKit dy → \(viaFlip)")
        }
      }
    }
    section.finish()
  }

  func testCoordsDisplayForPoint() {
    let section = Section("coords.displayForPoint")
    for c in (golden["coords"] as! [String: Any])["displayForPoint"] as! [[String: Any]] {
      let displays = (c["displays"] as! [Any]).map(rect)
      let got = Coords.displayIndexAtPoint(point(c["point"]), displays)
      section.check(got == (c["expect"] as! Int), "\(c["note"] ?? ""): \(got)")
    }
    section.finish()
  }

  func testCoordsClamp() {
    let section = Section("coords.clamp")
    for c in (golden["coords"] as! [String: Any])["clamp"] as! [[String: Any]] {
      let r = rect(c["rect"]), area = rect(c["area"])
      section.check(close(Coords.clampRectIntoArea(r, area), rect(c["clamp"])), "clamp \(r) into \(area) → \(Coords.clampRectIntoArea(r, area))")
      section.check(close(Coords.fitRectIntoArea(r, area), rect(c["fit"])), "fit \(r) into \(area) → \(Coords.fitRectIntoArea(r, area))")
    }
    section.finish()
  }

  func testCoordsRounding() {
    let section = Section("coords.rounding")
    let rounding = (golden["coords"] as! [String: Any])["rounding"] as! [String: Any]
    for c in rounding["roundHalfUp"] as! [[String: Any]] {
      let got = Coords.roundHalfUp(num(c["value"]))
      section.check(got == num(c["expect"]), "roundHalfUp(\(num(c["value"]))) = \(got)")
    }
    for c in rounding["rects"] as! [[String: Any]] {
      let r = rect(c["rect"])
      section.check(close(Coords.roundRect(r, .nearest), rect(c["nearest"])), "nearest \(r) → \(Coords.roundRect(r, .nearest))")
      section.check(close(Coords.roundRect(r, .enclosing), rect(c["enclosing"])), "enclosing \(r) → \(Coords.roundRect(r, .enclosing))")
    }
    section.finish()
  }

  func testDerivedRadii() {
    let section = Section("derived")
    for d in golden["derived"] as! [[String: Any]] {
      let diameter = num(d["diameter"])
      section.check(close(WheelMath.outerRadius(diameter), num(d["outerRadius"])), "outer \(diameter)")
      section.check(close(WheelMath.innerRadius(diameter, geometry), num(d["innerRadius"])), "inner \(diameter)")
      section.check(close(WheelMath.sectorOuterRadius(diameter, geometry), num(d["sectorOuterRadius"])), "sectorOuter \(diameter)")
    }
    section.finish()
  }
}
